            <div>
              <p class="stat-label">Total quizzes</p>
              <p class="stat-value">{{ totalQuizzes }}</p>
            </div>
          </div>

        </div>

        <!-- Skeleton stats -->
        <div v-else class="stats-grid">
          <div v-for="i in 6" :key="i" class="stat-card stat-card--skeleton">
            <div class="sk-icon"></div>
            <div class="sk-lines">
              <div class="sk-line sk-short"></div>
              <div class="sk-line sk-long"></div>
            </div>
          </div>
        </div>

        <!-- Charts row -->
        <div class="charts-row">
          <!-- Bar chart -->
          <div class="chart-card">
            <div class="chart-card-header">
              <span class="chart-card-title">Time spent</span>
              <div class="week-select week-select--sm" @click="chartWeekOpen = !chartWeekOpen">
                <span>{{ chartWeek }}</span>
                <svg width="14" height="14" fill="none" viewBox="0 0 24 24">
                  <path d="M6 9l6 6 6-6" stroke="#374151" stroke-width="2" stroke-linecap="round"/>
                </svg>
                <div v-if="chartWeekOpen" class="week-dropdown">
                  <div v-for="opt in weekOptions" :key="opt" class="week-option" :class="{ 'week-option--active': opt === chartWeek }" @click.stop="selectChartWeek(opt)">{{ opt }}</div>
                </div>
              </div>
            </div>
            <div class="bar-chart">
              <div class="bar-y-axis">
                <span v-for="v in [35,30,25,20,15,10,5,0]" :key="v">{{ v }}</span>
              </div>
              <div class="bar-area">
                <div v-for="day in chartData" :key="day.label" class="bar-col">
                  <div class="bar-track">
                    <div class="bar-val" :class="'bar-val--' + day.color" :style="{ height: (day.value / 36 * 100) + '%' }"></div>
                  </div>
                  <span class="bar-lbl">{{ day.label }}</span>
                </div>
              </div>
            </div>
          </div>

          <!-- Performance gauge -->
          <div class="perf-card">
            <span class="chart-card-title">Performance</span>
            <div class="perf-gauge">
              <svg width="160" height="160" viewBox="0 0 160 160">
                <circle cx="80" cy="80" r="64" fill="none" stroke="#f3f4f6" stroke-width="12"/>
                <circle cx="80" cy="80" r="64" fill="none"
                  :stroke="gaugeColor" stroke-width="12"
                  stroke-linecap="round"
                  :stroke-dasharray="gaugeDash"
                  transform="rotate(-90 80 80)"/>
              </svg>
              <div class="perf-inner">
                <span class="perf-pct">{{ perfPct }}%</span>
                <span class="perf-sub-label">Performance</span>
              </div>
            </div>
            <p class="perf-msg">{{ perfMsg }}</p>
          </div>
        </div>

        <!-- Course cards -->
        <div class="courses-row" v-if="enrollments.length > 0">
          <div v-for="c in enrollments.slice(0, 3)" :key="c.id" class="course-card">
            <RouterLink :to="`/courses/${c.id}`" class="course-card-link">
              <div class="course-cover">
                <img v-if="c.cover_image" :src="c.cover_image" :alt="c.title" class="cover-img" />
                <video v-else-if="c.first_video_url"
                       :src="c.first_video_url"
                       class="cover-img"
                       muted
                       preload="metadata"
                       @loadedmetadata="e => { e.target.currentTime = 1 }" />
                <div v-else class="cover-bg"></div>
              </div>
              <div class="course-body">
                <div class="course-top-row">
                  <span class="course-tag">{{ c.subject || 'Course' }}</span>
                  <div v-if="c.price > 0" class="course-price">
                    <span class="price-new">${{ Number(c.price).toFixed(2) }}</span>
                  </div>
                  <span v-else class="price-new">Free</span>
                </div>
                <h3 class="course-title">{{ c.title }}</h3>
                <div class="course-author">
                  <div class="author-avatar">
                    <svg width="16" height="16" fill="none" viewBox="0 0 24 24">
                      <path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2" stroke="#7b1f1f" stroke-width="2" stroke-linecap="round"/>
                      <circle cx="12" cy="7" r="4" stroke="#7b1f1f" stroke-width="2"/>
                    </svg>
                  </div>
                  <span class="author-name">{{ c.teacher_name || 'Bridge' }}</span>
                </div>
                <div class="course-meta">
                  <span class="meta-item">
                    <svg width="13" height="13" fill="none" viewBox="0 0 24 24">
                      <path d="M4 19.5A2.5 2.5 0 016.5 17H20" stroke="#9ca3af" stroke-width="2" stroke-linecap="round"/>
                      <path d="M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z" stroke="#9ca3af" stroke-width="2"/>
                    </svg>
                    {{ c.lessons_count ?? 0 }}
                  </span>
                  <span class="meta-dot">•</span>
                  <span class="meta-item">
                    <svg width="13" height="13" fill="none" viewBox="0 0 24 24">
                      <circle cx="12" cy="12" r="10" stroke="#9ca3af" stroke-width="2"/>
                      <path d="M12 6v6l4 2" stroke="#9ca3af" stroke-width="2" stroke-linecap="round"/>
                    </svg>
                    {{ formatDuration(c.total_duration_seconds) }}
                  </span>
                  <span class="meta-dot">•</span>
                  <span class="meta-item">
                    <span class="meta-progress">{{ progressMap[c.id] ?? 0 }}%</span>
                  </span>
                </div>
              </div>
            </RouterLink>
          </div>
        </div>

      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore }    from '@/stores/auth'
import { useCoursesStore } from '@/stores/courses'

const router = useRouter()
const auth   = useAuthStore()
const store  = useCoursesStore()

const userMenuOpen = ref(false)
const userInitial  = computed(() => (auth.user?.name || 'S')[0].toUpperCase())

function logout() {
  auth.logout()
  router.push('/login')
}

function closeMenu(e) {
  if (!e.target.closest('.topbar-user')) userMenuOpen.value = false
}

const loading     = ref(true)
const enrollments = computed(() => store.enrollments)
const progressMap = ref({})

const inProgressCount = computed(() =>
  enrollments.value.filter(c => {
    const p = progressMap.value[c.id] ?? 0
    return p < 100
  }).length
)

const finishedCount = computed(() =>
  enrollments.value.filter(c => (progressMap.value[c.id] ?? 0) === 100).length
)

const failCount = computed(() => 0)

const totalQuizzes = computed(() =>
  enrollments.value.reduce((sum, c) => sum + (store.progress[c.id]?.total_quizzes ?? 0), 0)
)

const perfPct = computed(() => {
  if (!enrollments.value.length) return 0
  const avg = enrollments.value.reduce((s, c) => s + (progressMap.value[c.id] ?? 0), 0) / enrollments.value.length
  return Math.round(avg)
})

const gaugeCircumference = 2 * Math.PI * 64
const gaugeDash = computed(() => {
  const filled = (perfPct.value / 100) * gaugeCircumference
  return `${filled.toFixed(2)} ${gaugeCircumference.toFixed(2)}`
})
const gaugeColor = computed(() => {
  if (perfPct.value >= 75) return '#22c55e'
  if (perfPct.value >= 45) return '#f59e0b'
  return '#ef4444'
})
const perfMsg = computed(() => {
  if (perfPct.value >= 75) return 'You did a great job!'
  if (perfPct.value >= 45) return 'Keep it up!'
  return 'Keep going, you can do it!'
})

const weekOptions = ['This Week', 'Last Week', '2 Weeks Ago']

const headerWeek = ref('This Week')
const headerWeekOpen = ref(false)
function selectHeaderWeek(opt) { headerWeek.value = opt; headerWeekOpen.value = false }

const chartWeek = ref('This Week')
const chartWeekOpen = ref(false)
function selectChartWeek(opt) { chartWeek.value = opt; chartWeekOpen.value = false }

const weekDataSets = {
  'This Week':   [
    { label: 'Mon', value: 17.5, color: 'purple' },
