    { label: 'Sun', value: 20,   color: 'peach'  },
    { label: 'Sat', value: 13,   color: 'purple' },
  ],
}

const chartData = computed(() => weekDataSets[chartWeek.value])

onMounted(async () => {
  document.addEventListener('click', closeMenu)
  try {
    await store.fetchEnrollments()
    await Promise.all(
      enrollments.value.map(async c => {
        try {
          await store.fetchProgress(c.id)
          progressMap.value[c.id] = store.progress[c.id]?.percentage ?? 0
        } catch {
          progressMap.value[c.id] = 0
        }
      })
    )
  } finally {
    loading.value = false
  }
})

onUnmounted(() => {
  document.removeEventListener('click', closeMenu)
})

function formatDuration(seconds) {
  const s = Number(seconds) || 0
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  if (!h && !m) return '—'
  if (!h) return `${m}m`
  return m ? `${h}h ${m}m` : `${h}h`
}
